INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4235042, 607713, 3746, '<td valign="top">I dont want to believe it, but is that you Alex without a beard??  OMG - great capture from this cult classic. You nailed the atmosphere perfectly. gotta be a ten.  adding to favs.</td>', 'I dont want to believe it, but is that you Alex without a beard??  OMG - great capture from this cult classic. You nailed the atmosphere perfectly. gotta be a ten.  adding to favs.', '2007-11-09 15:07:25.000000', NULL, 1),
(4235044, 608754, 3746, '<td valign="top">very very clever idea - could this possibly be an IreneM shot? regardless, a tried and tested technique made to fit the challenge perfectly.</td>', 'very very clever idea - could this possibly be an IreneM shot? regardless, a tried and tested technique made to fit the challenge perfectly.', '2007-11-09 15:07:38.000000', NULL, 1),
(4235046, 608814, 3746, '<td valign="top">One of the better sunsets (sunrises) I have seen on here for a while. suits the challenge well.</td>', 'One of the better sunsets (sunrises) I have seen on here for a while. suits the challenge well.', '2007-11-09 15:07:44.000000', NULL, 1),
(4235047, 608974, 3746, '<td valign="top">I like the old film stock feel you have recreated here. one of the better psycho shots., nice use of shadows/light. 8 well done.</td>', 'I like the old film stock feel you have recreated here. one of the better psycho shots., nice use of shadows/light. 8 well done.', '2007-11-09 15:07:46.000000', NULL, 1),
(4235050, 608767, 3746, '<td valign="top">Iconic image from the 80s, recreated real well here.. just revising votes etc and going to bump this up.. it really is very well done.</td>', 'Iconic image from the 80s, recreated real well here.. just revising votes etc and going to bump this up.. it really is very well done.', '2007-11-09 15:08:35.000000', NULL, 1),
(4235051, 608822, 66348, '<td valign="top">Noise works very nicely in your shot, lighting is spot on and your editing also works. Nice job. Return to bump score...</td>', 'Noise works very nicely in your shot, lighting is spot on and your editing also works. Nice job. Return to bump score...', '2007-11-09 15:08:47.000000', NULL, 1),
(4235053, 608947, 3746, '<td valign="top">great recreation of the one sheet. this was one of my favourite films when I was younger. would love to see a modern sequel (lets forget about the dreadful Gremlins 2 huh?) using up to date CGI. maybe it would lose some of its appeal if it was CGI.  anyway, I am rambling now. great shot, hope it does well. 8</td>', 'great recreation of the one sheet. this was one of my favourite films when I was younger. would love to see a modern sequel (lets forget about the dreadful Gremlins 2 huh?) using up to date CGI. maybe it would lose some of its appeal if it was CGI.  anyway, I am rambling now. great shot, hope it does well. 8', '2007-11-09 15:08:58.000000', NULL, 1),
(4235064, 609050, 3746, '<td valign="top">OK, already voted on this, but back to comment.<br/> <br/>A great reproduction of the one-sheet for this film. I reckon some are going to vote you down as this doesnt represent a scene, but in this case it is so well done I can''t help but vote it high. It was always going to be hard to replicate this as the two protagonists from the film are so distinctive looking, but you have captured the vibe here so the fact that the models dont look like Pitt &amp; Norton is easy to loverlook, although the Norton guy actually has nailed the sirk from the original poster.. brilliant idea, brilliantly executed. well done. bumping to 9</td>', 'OK, already voted on this, but back to comment. A great reproduction of the one-sheet for this film. I reckon some are going to vote you down as this doesnt represent a scene, but in this case it is so well done I can''t help but vote it high. It was always going to be hard to replicate this as the two protagonists from the film are so distinctive looking, but you have captured the vibe here so the fact that the models dont look like Pitt & Norton is easy to loverlook, although the Norton guy actually has nailed the sirk from the original poster.. brilliant idea, brilliantly executed. well done. bumping to 9', '2007-11-09 15:13:23.000000', NULL, 1),
(4235067, 607980, 3746, '<td valign="top">perfect use of grain and vignette. this probably wont do quite as well as it deserves to, but I am loving it.</td>', 'perfect use of grain and vignette. this probably wont do quite as well as it deserves to, but I am loving it.', '2007-11-09 15:13:31.000000', NULL, 1),
(4235071, 608275, 3746, '<td valign="top">OK, this is a great idea. My biggest issue with it is that Freddy Krueger is probably one of the most infamous movie icons of the 80s. Now his trademark was that horribly wicked glove. I Would of loved to of seen him holding it up in silhouette.. 8</td>', 'OK, this is a great idea. My biggest issue with it is that Freddy Krueger is probably one of the most infamous movie icons of the 80s. Now his trademark was that horribly wicked glove. I Would of loved to of seen him holding it up in silhouette.. 8', '2007-11-09 15:14:04.000000', NULL, 1),
(4235116, 608734, 70177, '<td valign="top">you dont  look as ripped as them guys did in the movie:P</td>', 'you dont  look as ripped as them guys did in the movie:P', '2007-11-09 15:30:35.000000', NULL, 1),
(4235230, 608979, 73929, '<td valign="top">Very Hitchcock... your model looks amazingly like Janet Leigh!  10 for me!  :)</td>', 'Very Hitchcock... your model looks amazingly like Janet Leigh!  10 for me!  :)', '2007-11-09 16:29:32.000000', NULL, 1),
