(4235696, 607556, 76430, '<td valign="top">Oh NO, save woodie Charlie!  I like the combination of gears, but the focus is a little soft.  I haven''t seen the movie so I don''t know if this is a scene from it or not, so I''ll assume this is what happened to Chaplin.</td>', 'Oh NO, save woodie Charlie!  I like the combination of gears, but the focus is a little soft.  I haven''t seen the movie so I don''t know if this is a scene from it or not, so I''ll assume this is what happened to Chaplin.', '2007-11-09 20:25:17.000000', NULL, 1),
(4235738, 608557, 86466, '<td valign="top">Great colour and use of light - love it</td>', 'Great colour and use of light - love it', '2007-11-09 20:59:13.000000', NULL, 1),
(4235743, 608854, 86466, '<td valign="top">Nice composition</td>', 'Nice composition', '2007-11-09 21:04:01.000000', NULL, 1),
(4235795, 608445, 83817, '<td valign="top">One of my favorite movies and actors (Mandy Patinkin)</td>', 'One of my favorite movies and actors (Mandy Patinkin)', '2007-11-09 21:43:59.000000', NULL, 1),
(4236012, 608946, 60862, '<td valign="top">Excellent!</td>', 'Excellent!', '2007-11-09 23:26:02.000000', NULL, 1),
(4236023, 608445, 77196, '<td valign="top">I want to like this, but the contents of his hands are not clear - especially the model''s right hand. Facial expression, costume, and lighting are good.</td>', 'I want to like this, but the contents of his hands are not clear - especially the model''s right hand. Facial expression, costume, and lighting are good.', '2007-11-09 23:31:10.000000', NULL, 1),
(4236027, 608615, 60862, '<td valign="top">Not a bad idea, but it''s very dark and blurry.  If you want a dark feeling, try shooting it lighter, which will let you get better focus and a faster shutter speed.  Then you can edit it to be darker.</td>', 'Not a bad idea, but it''s very dark and blurry.  If you want a dark feeling, try shooting it lighter, which will let you get better focus and a faster shutter speed.  Then you can edit it to be darker.', '2007-11-09 23:31:40.000000', NULL, 1),
(4236041, 608737, 86306, '<td valign="top">nice shot</td>', 'nice shot', '2007-11-09 23:37:18.000000', NULL, 1),
(4236043, 607110, 60862, '<td valign="top">Interesting shapes from the moving bird.  I bet this is getting voted pretty low, but I kind of like it.</td>', 'Interesting shapes from the moving bird.  I bet this is getting voted pretty low, but I kind of like it.', '2007-11-09 23:37:57.000000', NULL, 1),
(4236092, 608974, 86460, '<td valign="top">Creative lighting but too difficult to pin point purpose of image - what should I be looking at.</td>', 'Creative lighting but too difficult to pin point purpose of image - what should I be looking at.', '2007-11-09 23:56:54.000000', NULL, 1),
(4236095, 608754, 86460, '<td valign="top">Nice capture but not very compelling subject matter.</td>', 'Nice capture but not very compelling subject matter.', '2007-11-09 23:57:23.000000', NULL, 1),
(4236097, 609026, 86460, '<td valign="top">The composition just isn''t compelling or in any way pleasant.</td>', 'The composition just isn''t compelling or in any way pleasant.', '2007-11-09 23:58:03.000000', NULL, 1),
(4236104, 608814, 86460, '<td valign="top">Wonderful colors with nice silhoutte. Power lines are distracting and, once noticed, ruin the composition.</td>', 'Wonderful colors with nice silhoutte. Power lines are distracting and, once noticed, ruin the composition.', '2007-11-09 23:59:12.000000', NULL, 1),
(4236105, 608820, 86460, '<td valign="top">Wonderful character shot. The bright region just over subjects left shoulder is a bit of a distraction, otherwise I love the composition and lighting.</td>', 'Wonderful character shot. The bright region just over subjects left shoulder is a bit of a distraction, otherwise I love the composition and lighting.', '2007-11-10 00:00:04.000000', NULL, 1),
(4236108, 607556, 86460, '<td valign="top">OK but what am I seeing. Is that a wooden figure being crunched?</td>', 'OK but what am I seeing. Is that a wooden figure being crunched?', '2007-11-10 00:00:50.000000', NULL, 1),
(4236111, 608851, 86460, '<td valign="top">Full depth of focus would have been much more compelling, in my opinion.</td>', 'Full depth of focus would have been much more compelling, in my opinion.', '2007-11-10 00:01:24.000000', NULL, 1),
(4236116, 608731, 86460, '<td valign="top">Very nice pose but the background is brighter than the subject and that always is distracting.</td>', 'Very nice pose but the background is brighter than the subject and that always is distracting.', '2007-11-10 00:02:03.000000', NULL, 1),
(4236126, 608460, 86460, '<td valign="top">Shadows are a bit out of control and the gun barrel is a bit out of focus. I''m not sure what the meaning of this photo is.</td>', 'Shadows are a bit out of control and the gun barrel is a bit out of focus. I''m not sure what the meaning of this photo is.', '2007-11-10 00:04:52.000000', NULL, 1),
(4236131, 608742, 86460, '<td valign="top">Very nice colors and texture on the water. However, the ducks appear to be an "after thought" in this composition. Are they supposed to be the focal point?</td>', 'Very nice colors and texture on the water. However, the ducks appear to be an "after thought" in this composition. Are they supposed to be the focal point?', '2007-11-10 00:05:49.000000', NULL, 1),
(4236133, 607392, 86460, '<td valign="top">Too many distracting elements in background.</td>', 'Too many distracting elements in background.', '2007-11-10 00:06:22.000000', NULL, 1),
(4236135, 607980, 86460, '<td valign="top">Too creative for my tastes. I''m not sure what the bright object is on right hand side of frame.</td>', 'Too creative for my tastes. I''m not sure what the bright object is on right hand side of frame.', '2007-11-10 00:07:12.000000', NULL, 1),
(4236138, 606697, 86460, '<td valign="top">Skin tones just don''t work especially facial area.</td>', 'Skin tones just don''t work especially facial area.', '2007-11-10 00:07:42.000000', NULL, 1),
(4236140, 608174, 86460, '<td valign="top">Too many scene elements.</td>', 'Too many scene elements.', '2007-11-10 00:08:03.000000', NULL, 1),
(4236192, 608174, 656, '<td valign="top">that''s a lot of ducks.  Like the angle you found.</td>', 'that''s a lot of ducks.  Like the angle you found.', '2007-11-10 00:22:56.000000', NULL, 1),
(4236195, 607556, 656, '<td valign="top">took a while to see the ghost in the machine</td>', 'took a while to see the ghost in the machine', '2007-11-10 00:23:36.000000', NULL, 1),
(4236208, 607688, 656, '<td valign="top">this is a great shot.  For some reason the dog just makes it for me.  Not sure I really get the movie tie-in though.</td>', 'this is a great shot.  For some reason the dog just makes it for me.  Not sure I really get the movie tie-in though.', '2007-11-10 00:27:42.000000', NULL, 1),
(4236213, 608767, 656, '<td valign="top">interesting light, but the focus seems quite off</td>', 'interesting light, but the focus seems quite off', '2007-11-10 00:29:55.000000', NULL, 1),
(4236222, 608519, 656, '<td valign="top">that''s quite a different view of that movie</td>', 'that''s quite a different view of that movie', '2007-11-10 00:32:30.000000', NULL, 1),
(4236391, 608691, 36006, '<td valign="top">Three things.<br/> <br/>This would of been a better pix if I could of seen her expression on her face instead of her back side.<br/> <br/>This would of been a better pix if it were sharp out of the camera.<br/> <br/>This would of been a better pix if the black lines on the wall were not cutting through your model.</td>', 'Three things. This would of been a better pix if I could of seen her expression on her face instead of her back side. This would of been a better pix if it were sharp out of the camera. This would of been a better pix if the black lines on the wall were not cutting through your model.', '2007-11-10 02:03:56.000000', NULL, 1),
(4236392, 608820, 36006, '<td valign="top">I see the old man, but where is the proof that he is even near the ocean. Come on, throw a bone. Give a skiff, a fishing pole, water, sand, something.</td>', 'I see the old man, but where is the proof that he is even near the ocean. Come on, throw a bone. Give a skiff, a fishing pole, water, sand, something.', '2007-11-10 02:06:11.000000', NULL, 1),
(4236393, 608669, 36006, '<td valign="top">OK, I see the marsh, but, where are the children?</td>', 'OK, I see the marsh, but, where are the children?', '2007-11-10 02:06:48.000000', NULL, 1),
