(4237528, 608445, 1054, '<td valign="top">Love the movie. Your model seems more tired or bored than vengeful; he probably also needs a sword to really make this work. Also, it appears that NeatImage, or something similar, may have been applied too heavily -- the hands seem a bit plastic.</td>', 'Love the movie. Your model seems more tired or bored than vengeful; he probably also needs a sword to really make this work. Also, it appears that NeatImage, or something similar, may have been applied too heavily -- the hands seem a bit plastic.', '2007-11-10 19:14:31.000000', NULL, 1),
(4237530, 608754, 1054, '<td valign="top">Very nicely done! An interesting twist on the waterdrop.</td>', 'Very nicely done! An interesting twist on the waterdrop.', '2007-11-10 19:16:07.000000', NULL, 1),
(4237533, 608974, 1054, '<td valign="top">Excelent. You''ve created a mood and a feel that is very true to the original.</td>', 'Excelent. You''ve created a mood and a feel that is very true to the original.', '2007-11-10 19:17:08.000000', NULL, 1),
(4237540, 608915, 1054, '<td valign="top">Given my past experience, I bet you''re getting dinged for the dirty hands, however it''s true to the movie so I''m bumping you up for same.</td>', 'Given my past experience, I bet you''re getting dinged for the dirty hands, however it''s true to the movie so I''m bumping you up for same.', '2007-11-10 19:18:37.000000', NULL, 1),
