(4237548, 608767, 1054, '<td valign="top">Excellent lighting and pose! A slightly tighter crop at the top and left may have made this even stronger.</td>', 'Excellent lighting and pose! A slightly tighter crop at the top and left may have made this even stronger.', '2007-11-10 19:22:57.000000', NULL, 1),
(4237550, 608275, 1054, '<td valign="top">Great exposure.</td>', 'Great exposure.', '2007-11-10 19:23:16.000000', NULL, 1),
(4237554, 608460, 1054, '<td valign="top">Brilliant!</td>', 'Brilliant!', '2007-11-10 19:24:49.000000', NULL, 1),
