(4238935, 608974, 34659, '<td valign="top">Scary.  Thrilling.  Eery.  Suspenseful.  Alfred Hitchcock would be proud.  You managed to convey a very strong emotion without resorting to gratuitous violence &amp; gore.</td>', 'Scary.  Thrilling.  Eery.  Suspenseful.  Alfred Hitchcock would be proud.  You managed to convey a very strong emotion without resorting to gratuitous violence & gore.', '2007-11-11 19:07:22.000000', NULL, 1),
(4238936, 607688, 34659, '<td valign="top">I''ve never seen the film, but this is one helluva shot.  This image speaks volumes - tells tales - making it difficult to believe that it doesn''t support the intended movie (and I have no frame of reference).</td>', 'I''ve never seen the film, but this is one helluva shot.  This image speaks volumes - tells tales - making it difficult to believe that it doesn''t support the intended movie (and I have no frame of reference).', '2007-11-11 19:08:29.000000', NULL, 1),
